import test from 'node:test';
import assert from 'node:assert/strict';
import {normalize,diffCatalog,COMMIT} from './catalog.mjs';
import {validate,createDraft,patchDraft,loadRegistry} from './runtime.mjs';
const registry=schema=>({baselineCommit:COMMIT,resources:{'test/schema.json':{schema,issues:[]}}});
const id='test/schema.json';
test('product embedded constraints retained and unresolved extensions block',()=>{const issues=[];const s=normalize({configurations:{rows:{valueType:'array',description:'{"type":"array","minItems":1,"items":{"type":"string"}}'},code:{valueType:'{{contextVariableType}}',isFormula:true}}},'',issues);assert.equal(s.properties.rows.minItems,1);assert.ok(issues.some(x=>x.code==='UNRESOLVED_VALUE_TYPE'));assert.equal(validate({resources:{[id]:{schema:s,issues}}},id,{rows:['x']}).status,'blocked');});
test('no coercion, false values and existing fields survive patch',()=>{const reg=registry({type:'object',required:['id','enabled'],properties:{id:{type:'string'},enabled:{type:'boolean'},name:{type:'string'}}});const original={id:'keep',enabled:true,name:'old'};const r=patchDraft(reg,id,original,{enabled:false});assert.equal(r.draft.enabled,false);assert.equal(r.draft.name,'old');assert.equal(original.enabled,true);assert.throws(()=>patchDraft(reg,id,original,{id:'change'}),/IDENTITY/);assert.throws(()=>createDraft(reg,id,{id:'x',enabled:'false'}),/NOT_VALIDATED/);});
test('required, enum, bounds and extra properties',()=>{const reg=registry({type:'object',required:['n'],properties:{n:{type:'integer',minimum:1,maximum:3},mode:{enum:['a','b']}},additionalProperties:false});assert.equal(validate(reg,id,{n:2,mode:'a'}).valid,true);for(const v of [{},{n:0},{n:4},{n:1.5},{n:1,mode:'c'},{n:1,extra:1}])assert.equal(validate(reg,id,v).valid,false);});
test('oneOf anyOf not if and false schema',()=>{assert.equal(validate(registry({oneOf:[{type:'number'},{minimum:0}]}),id,2).valid,false);assert.equal(validate(registry({anyOf:[{type:'string'},{type:'number'}]}),id,false).valid,false);assert.equal(validate(registry({not:{const:'x'}}),id,'x').valid,false);assert.equal(validate(registry({if:{const:1},then:false,else:true}),id,1).valid,false);assert.equal(validate(registry(false),id,{}).valid,false);});
test('references resolve across resources and cannot fetch network',()=>{const reg=registry({$ref:'../other/schema.json#/$defs/name'});reg.resources['other/schema.json']={schema:{$defs:{name:{type:'string',minLength:2}}},issues:[]};assert.equal(validate(reg,id,'ok').valid,true);assert.equal(validate(reg,id,'').valid,false);reg.resources[id].schema.$ref='https://example.invalid/schema';assert.equal(validate(reg,id,'ok').status,'blocked');});
test('unsupported constraints cannot pass',()=>{for(const schema of [{unevaluatedProperties:false},{format:'email'}])assert.equal(validate(registry(schema),id,{}).status,'blocked');});
test('snapshot diff records additions removals and changed hashes',()=>{assert.deepEqual(diffCatalog({resources:[{id:'a',sha256:'1'},{id:'b',sha256:'2'}]},{resources:[{id:'a',sha256:'3'},{id:'c',sha256:'4'}]}),{added:['c'],removed:['b'],changed:['a']});});
test('real action definition validates draft and rejects missing steps or extra fields',()=>{const reg=loadRegistry(),key='workflow/action/schema.json';const input={id:'c0ca39af-35b8-4ee2-bb30-091ebd520000',name:'Validation draft',steps:[{type:'setvar'}]};assert.equal(createDraft(reg,key,input).draft.name,input.name);assert.equal(validate(reg,key,{...input,steps:[]}).valid,false);assert.equal(validate(reg,key,{...input,unrecognized:true}).valid,false);});
test('all priority contracts return explicit structural, invalid or blocked states',()=>{const reg=loadRegistry();assert.equal(Object.keys(reg.resources).length,159);for(const key of Object.keys(reg.resources)){const r=validate(reg,key,{});assert.ok(['blocked','invalid','structurally-valid'].includes(r.status),key);assert.ok(!r.valid||r.proof.includes('structure-only'),key);}});
